        let eps = 1e-4;
        let b = op.dot(r.d);
        let det = b * b - op.dot(op) + self.rad * self.rad;
        if det < 0.0 {
            0.0
        } else {
            let det = det.sqrt();
            let t1 = b - det;
            if t1 > eps {
                t1
            } else {
                let t2 = b + det;
                if t2 > eps {
                    t2
                } else {
                    0.0
                }
            }
        }
    }
}

