#[derive(Clone)]
struct Ray {
    o: Vec,
    d: Vec,
}

#[derive(Clone, Copy, PartialEq)]
enum ReflT {
    DIFF,
    SPEC,
    REFR,
}

struct Sphere {
    rad: f64,
    p: Vec,
    e: Vec,
    c: Vec,
    refl: ReflT,
}

impl Sphere {
    fn new(rad: f64, p: Vec, e: Vec, c: Vec, refl: ReflT) -> Self {
        Sphere { rad, p, e, c, refl }
    }

    fn intersect(&self, r: &Ray) -> f64 {
        let op = self.p - r.o;
        let eps = 1e-4;
        let b = op.dot(&r.d);
        let det = b * b - op.dot(&op) + self.rad * self.rad;

        if det < 0.0 {
            0.0
        } else {
            let det = det.sqrt();
            let t = b - det;
            if t > eps {
                t
            } else {
                let t = b + det;
                if t > eps {
                    t
                } else {
                    0.0
                }
            }
        }
    }
}

