        let op = self.p - r.o;
        let eps = 1e-4;
        let b = op.dot(r.d);
        let det = b * b - op.dot(op) + self.rad * self.rad;

        if det < 0.0 {
            INFINITY
        } else {
            let det_sqrt = det.sqrt();
            let t = b - det_sqrt;
            if t > eps {
                t
            } else {
                let t2 = b + det_sqrt;
                if t2 > eps {
                    t2
                } else {
                    INFINITY
                }
            }
        }
    }
}

