fn radiance(r: &Ray, depth: usize) -> Vec {
    let mut t: f64 = 0.0;
    let mut id = 0;
    if !intersect(r, &mut t, &mut id) {
        return Vec::new(0.0, 0.0, 0.0);
    }

    let spheres = SPHERES.get().unwrap();

    let obj = &spheres[id];
    let x = r.o + r.d * t;
    let mut n = x - obj.p;
    n.norm();
    let nl = if n.dot(r.d) < 0.0 { n } else { n * -1.0 };
    let mut f = obj.c;
    let p = f.x.max(f.y).max(f.z);

    if depth > 5 {
