}

type TriggerTemplate = Vec<Action>;

const CENTI_PIXELS_PER_PIXEL: i32 = 100;

// Bug struct, representing moving elements
struct Bug {
    x: i32,
    y: i32,
    id: TileId,
    increasing: bool,
    wait: i32,
}

impl Bug {
    fn new(x: i32, y: i32, id: TileId) -> Self {
        Bug {
            x,
            y,
            id,
            increasing: true,
            wait: 0,
        }
    }

    fn distance_to(&self, t_x: i32, t_y: i32) -> i32 {
